@EventHandler( payloadType=RemoveAssignmentsFromShiftEvent.class)
public void handle( RemoveAssignmentsFromShiftEvent event) {
    LOGGER.info("handling RemoveAssignmentsFromShiftEvent - " + event );

    Shift entity = removeFromAssignments(event.getShiftId(), event.getRemoveFrom() );
    
	// ------------------------------------------
	// emit to subscribers that find one
	// ------------------------------------------    	
    emitFindShift( entity );

	// ------------------------------------------
	// emit to subscribers that find all
	// ------------------------------------------    	
    emitFindAllShift( entity );
}



    /**
     * Method to retrieve the Shift via an ShiftPrimaryKey.
     * @param 	id Long
     * @return 	Shift
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Shift handle( FindShiftQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getShiftId() );
    }
    
    /**
     * Method to retrieve a collection of all Shifts
     *
     * @param	query	FindAllShiftQuery 
     * @return 	List<Shift> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Shift> handle( FindAllShiftQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindShift,
 * but only if the id matches
 *
 * @param		entity	Shift
 */
	protected void emitFindShift( Shift entity ) {
		LOGGER.info("handling emitFindShift" );
		
	    queryUpdateEmitter.emit(FindShiftQuery.class,
	                            query -> query.getFilter().getShiftId().equals(entity.getShiftId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllShift
	 * 
	 * @param		entity	Shift
	 */
	protected void emitFindAllShift( Shift entity ) {
		LOGGER.info("handling emitFindAllShift" );
		
	    queryUpdateEmitter.emit(FindAllShiftQuery.class,
	                            query -> true,
	                            entity);
	}

